export function InformationArchitecture({
  highlightLevel = "{{highlightLevel}}",
  showLines = {{showLines}},
  accent = "{{accent}}",
}) {
  const fill = (key) => (highlightLevel === key ? accent : "#fff");
  const stroke = (key) => (highlightLevel === key ? "#241430" : "#24143022");
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <svg viewBox="0 0 300 120" width="100%" height="120" aria-hidden="true" style={{ display: "block" }}>
        {showLines && (<>
          <line x1="40" y1="20" x2="40" y2="55" stroke="#24143044" strokeWidth="1.5" />
          <line x1="40" y1="55" x2="110" y2="55" stroke="#24143044" strokeWidth="1.5" />
          <line x1="40" y1="55" x2="190" y2="55" stroke="#24143044" strokeWidth="1.5" />
          <line x1="110" y1="55" x2="110" y2="90" stroke="#24143044" strokeWidth="1.5" />
          <line x1="110" y1="90" x2="70" y2="90" stroke="#24143044" strokeWidth="1.5" />
          <line x1="110" y1="90" x2="150" y2="90" stroke="#24143044" strokeWidth="1.5" />
        </>)}
        <rect x="8" y="6" width="64" height="26" rx="6" fill={fill("home")} stroke={stroke("home")} />
        <text x="40" y="23" textAnchor="middle" fontSize="10" fontFamily="system-ui">Home</text>
        <rect x="78" y="42" width="64" height="26" rx="6" fill={fill("category")} stroke={stroke("category")} />
        <text x="110" y="59" textAnchor="middle" fontSize="10" fontFamily="system-ui">Category</text>
        <rect x="158" y="42" width="64" height="26" rx="6" fill="#fff" stroke="#24143022" />
        <text x="190" y="59" textAnchor="middle" fontSize="10" fontFamily="system-ui">Category</text>
        <rect x="38" y="77" width="64" height="26" rx="6" fill={fill("item")} stroke={stroke("item")} />
        <text x="70" y="94" textAnchor="middle" fontSize="10" fontFamily="system-ui">Item</text>
        <rect x="118" y="77" width="64" height="26" rx="6" fill="#fff" stroke="#24143022" />
        <text x="150" y="94" textAnchor="middle" fontSize="10" fontFamily="system-ui">Item</text>
      </svg>
      <p style={{ margin: "8px 0 0" }}>Content, navigation and functionality organised into a structure &mdash; {highlightLevel} level highlighted</p>
    </div>
  );
}
